public class frm_SettingApprovalDetail : frm_SettingReport
{
	private readonly IHttpClient _httpClient = HttpClientHelperFactory.GetHttpClient();

	private IContainer components;

	public frm_SettingApprovalDetail()
	{
		InitializeComponent();
		tab_dashboard.TabPages[0].PageVisible = true;
		tab_dashboard.TabPages[2].PageVisible = false;
		tab_dashboard.TabPages[3].PageVisible = false;
		gc_ReportId.FieldName = "ApprovalObjectType";
		gc_ReportId.Caption = "Object Type";
		gc_ReportName.Visible = false;
		OnLoadAsync += frm_SettingApprovalDetail_Load;
	}

	public override async Task LoadHeader()
	{
		_ = 1;
		try
		{
			gv_listReport.GetFocusedRowCellValue(gc_DocEntry);
			gv_listReport.GetFocusedRow();
			DataTable dataSource = await _httpClient.SettingApprovalDetail.GetDataHeaderById(Function.ParseInt(Function.ToString(gv_listReport.GetFocusedRowCellValue(gc_DocEntry))));
			grd_Header.DataSource = dataSource;
			grd_Header.RefreshDataSource();
			DataTable dataTable = await _httpClient.FormFilterSettingClient.GetDataTableByTableName("ODRF");
			dataTable.Rows.Add("");
			dataTable.AcceptChanges();
			luk_HeaderFieldName.DataSource = dataTable;
			luk_HeaderFieldName.DisplayMember = "COLUMN_NAME";
			luk_HeaderFieldName.ValueMember = "COLUMN_NAME";
			luk_HeaderDataType.DataSource = _dataTypeHeader;
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
		}
	}

	private async Task frm_SettingApprovalDetail_Load(object sender, EventArgs e)
	{
		await LoadData();
	}

	private async Task LoadData()
	{
		_ = 1;
		try
		{
			await LoadHeader();
			await LoadLineFieldName();
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
		}
	}

	public override async void SetDataLukField(string code)
	{
		try
		{
		}
		catch (Exception ex)
