			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
		}
	}

	public override void LoadCFLButtonHeader()
	{
		try
		{
			btn_reportGrid.TypeCFL = Enums.TypeCFL.ApprovalObjectType;
			btn_reportGrid.RefreshDataSource();
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
		}
	}

	public override async Task<DataTable> LoadData(int id, string fromDate, string toDate, string objectType)
	{
		try
		{
			return await _httpClient.SettingApprovalDetail.LoadData(id, fromDate, toDate, objectType);
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
			return new DataTable();
		}
	}

	public override async Task<DataTable> GetLineById(int id)
	{
		try
		{
			return await _httpClient.SettingApprovalDetail.GetAllLineById(id);
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
			return new DataTable();
		}
	}

	public async Task LoadLineFieldName()
	{
		try
		{
			DataTable dataTable = await _httpClient.FormFilterSettingClient.GetDataTableByTableName("DRF1");
			dataTable.Rows.Add("");
			dataTable.AcceptChanges();
			luk_FieldName.DataSource = dataTable;
			luk_FieldName.DisplayMember = "COLUMN_NAME";
			luk_FieldName.ValueMember = "COLUMN_NAME";
			luk_currencyField.DataSource = dataTable;
			luk_currencyField.ValueMember = "COLUMN_NAME";
			luk_currencyField.DisplayMember = "COLUMN_NAME";
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
		}
	}

	public override void HeaderDelete()
	{
		try
		{
			gv_Header.DeleteRow(gv_Header.FocusedRowHandle);
			gv_Header.RefreshData();
			if (!isAddNew)
			{
				SetStatus(saveType.Update);
			}
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
		}
	}

	public override void HeaderAddNew()
	{
		try
		{
			try
			{
				if (!isAddNew)
				{
					SetStatus(saveType.Update);
				}
				DataTable dataTable = grd_Header.DatasourceTable();
				string obj = "0";
				if (dataTable.IsNotNull())
				{
					obj = dataTable.AsEnumerable().Max((DataRow r) => r["OrderId"]).ToString();
				}
				DataRow dataRow = dataTable.NewRow();
				dataRow["OrderId"] = Function.ParseInt(obj) + 1;
				dataRow["DataType"] = "normal";
				dataTable.Rows.Add(dataRow.ItemArray);
				grd_Header.DataSource = dataTable;
				grd_Header.RefreshDataSource();
			}
			catch (Exception ex)
			{
				Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
				WinCommons.ErrorLineNumber(ex);
			}
		}
		catch (Exception ex2)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex2.Message);
			WinCommons.ErrorLineNumber(ex2);
		}
	}

	public override async Task<HttpResult> AddNew()
	{
		try
		{
			DataTable dataTable = ((DataRowView)gv_listReport.GetFocusedRow()).Row.Table.Clone();
			dataTable.Rows.Add(((DataRowView)gv_listReport.GetFocusedRow()).Row.ItemArray);
			dataTable.AcceptChanges();
			DataTable table = ((DataView)gv_listProperties.DataSource).ToTable().Copy();
			DataTable table2 = ((DataView)gv_Header.DataSource).ToTable().Copy();
			DataSet dataSet = new DataSet();
			dataSet.Tables.Add(dataTable);
			dataSet.Tables.Add(table);
			dataSet.Tables.Add(table2);
			dataSet.AcceptChanges();
			return await _httpClient.SettingApprovalDetail.Add(dataSet);
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
			return new HttpResult
			{
				MessageCode = Enums.MessageCode.ExceptionMessage,
				Message = ex.Message
			};
		}
	}

	public override async Task<HttpResult> UpdateAction()
	{
		try
		{
			DataTable dataTable = ((DataRowView)gv_listReport.GetFocusedRow()).Row.Table.Clone();
			dataTable.Rows.Add(((DataRowView)gv_listReport.GetFocusedRow()).Row.ItemArray);
			dataTable.AcceptChanges();
			DataTable table = ((DataView)gv_listProperties.DataSource).ToTable().Copy();
			DataTable table2 = ((DataView)gv_Header.DataSource).ToTable().Copy();
			DataSet dataSet = new DataSet();
			dataSet.Tables.Add(dataTable);
			dataSet.Tables.Add(table);
			dataSet.Tables.Add(table2);
			dataSet.AcceptChanges();
			return await _httpClient.SettingApprovalDetail.Update(dataSet);
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
			return new HttpResult
			{
				MessageCode = Enums.MessageCode.ExceptionMessage,
				Message = ex.Message
			};
		}
	}

	public override async Task<string> DeleteAction(string id)
	{
		try
		{
			return await _httpClient.SettingApprovalDetail.DeleteDocs(id);
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
			return ex.Message;
		}
	}

	public override void btn_reportGrid_SelectedFromCFL(object sender, ButtonEditCFLEventArgs e)
	{
		try
		{
			string code = Function.ToString(e.ChooseItem["Code"]);
			Function.ToString(e.ChooseItem["Name"]);
			SetDataLukField(Function.ToString(code));
			if ((from x in grd_listReport.DataSourceTable.Copy().AsEnumerable()
				where Function.ToString(x["ApprovalObjectType"]) == Function.ToString(code)
				select x).Count() > 0)
			{
				WinCommons.Warning(Enums.MessageCode.None, "The Approval Object Type already exists");
			}
		}
		catch (Exception ex)
		{
			Logging.Write("ERROR", new StackTrace(new StackFrame(0)).ToString().Substring(5, new StackTrace(new StackFrame(0)).ToString().Length - 5), ex.Message);
			WinCommons.ErrorLineNumber(ex);
		}
	}

	protected override void Dispose(bool disposing)
	{
		if (disposing && components != null)
		{
			components.Dispose();
		}
		base.Dispose(disposing);
	}

